mapper.select:
SELECT
    gi.*,
    gt.`name` as typeName,
    u.user_name as userName,
    u.avatar
FROM
    `travel_group_info` gi
LEFT JOIN `travel_group_type` gt ON gi.type_id = gt.id
LEFT JOIN `tb_user` u ON gi.user_id = u.user_id

    
        and gi.user_id = #{param.userId}
    
    
        and u.user_name like concat('%', #{param.userName} ,'%')
    
    
        and gi.type_id = #{param.typeId}
    
    
        and gt.`name` like concat('%', #{param.typeName} ,'%')
    
    
        and gi.name like concat('%', #{param.name} ,'%')
    
    
        and gi.apply_condition = #{param.applyCondition}
    
    
        and gi.province = #{param.province}
    
    
        and gi.city = #{param.city}
    
    
        and gi.region = #{param.region}
    
    
        and gi.audit_status = #{param.auditStatus}
    

order by gi.create_time desc

SELECT gi.*, gt.`name` as typeName, u.user_name as userName FROM `travel_group_info` gi LEFT JOIN `travel_group_type` gt ON gi.type_id = gt.id LEFT JOIN `tb_user` u ON gi.user_id = u.user_id where gi.user_id = #{param.userId}
and gi.status = #{param.status}
and gi.audit_status = #{param.auditStatus}
order by gi.create_time desc
